class Panel {
	constructor(pvect, id) {
		this.pvect = createVector(0, 0, 0);
		this.tpvect = pvect;
		this.id = id;
		this.length = random(height, 2 * height);
	}
	move() {
		this.pvect.lerp(this.tpvect, 0.05);
	}
	show() {
		push();
		rotateX(this.pvect.x);
		rotateY(this.pvect.y);
		rotateZ(this.pvect.z);
		translate(height / 2, 0, 0);
		rotateX(twist.x);
		rotateY(HALF_PI + twist.y);
		rotateZ(twist.z);
		noStroke();
		plane(height / (1.5*pscale), height / (1.5*pscale));
		if(partyOn) {
			rotateY(-HALF_PI);
			translate(this.length*stretch, 0, 0);
			rotateY(HALF_PI);
			ellipse(0, 0, height/20, height/20);
		}
		pop();
	}
}

