// See https://github.com/aferriss/p5jsShaderExamples

let ang, avel;
let capture;
let twist;
let panels = [];
let button1, button2, button3, pbutton;
let sliderx, slidery, sliderz, sliderp, sliders;
let zoom = 0.6;
let ztarget = 0.6;
let shift = false;
let pscale = 8;
let ptarget = 8;
let fx, cam;
let restoring = false;
let start;
let auto = true;
let partyOn = false;
let bspeed = 0;
let tbspeed = 0.005;
let obspeed;
let audio;
let stretch = 0;

// Music downloaded from the freemusicarchive.org
// Distributed by the artist without copyright
// https://freemusicarchive.org/music/wax-lyricist/
function preload(){
	audio = loadSound('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/brassbrigade.mp3');
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	cam = camera(0, -height, (height / 2) / tan(PI / 6), 0, 0, 0, -0.25, 1, 0);
	capture = createCapture(VIDEO);
	capture.hide();
	ang = createVector(0, 0, HALF_PI);
	start = createVector(0, 0, HALF_PI);
	avel = createVector(0, 0, 0);
	twist = createVector(0, 0, 0);
	makeMirrorMagic();
	makeInputs();
	setTimeout(makePanels, 1500); //Allow time for video to come up
	audio.onended(restore);
}

function makeMirrorMagic() {
	fx = createShader(`
    attribute vec3 aPosition;
    attribute vec2 aTexCoord;
    attribute vec3 aNormal;
    uniform mat4 uProjectionMatrix;
    uniform mat4 uModelViewMatrix;
    uniform mat4 uNormalMatrix;
    varying vec3 vNormal;
    varying vec3 vEye;
    void main() { 
      vEye = normalize( vec3(uModelViewMatrix * vec4(aPosition, 1.0)));
      vNormal = normalize((uModelViewMatrix * vec4(aNormal, 0.0)).xyz);
      vec4 positionVec4 = vec4(aPosition, 1.0);
      gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    }`, `
    precision mediump float;
    varying vec3 vNormal;
    varying vec3 vEye;
    uniform sampler2D uMatcapTexture;
    vec2 matcap(vec3 eye, vec3 normal) {
      vec3 reflected = reflect(eye, normal);
      float m = 2.8284271247461903 * sqrt( reflected.z+1.0 );
      return reflected.xy / m + 0.5;
    }
    void main() {
      vec2 uv = matcap(vEye, vNormal) ;
      vec4 color = texture2D(uMatcapTexture, uv);
      gl_FragColor = color;
    }`);
}

function makePanels() {
	var id = 0;
	const ydiv = 18; // If animation is laggy, reduce this value to reduce the number of mirrors!
	for (let ay = PI / ydiv; ay <= (ydiv - 1) * PI / ydiv; ay += (Math.max(0.001, Math.abs(PI / ydiv)) || 1)) {
		let xdiv = floor(map(sin(ay), 0, 1, 2, ydiv - 1));
		for (let ax = 0; ax < TWO_PI; ax += (Math.max(0.001, Math.abs(PI / xdiv)) || 1)) {
			let pvect = createVector(ax, ay, 0);
			panels.push(new Panel(pvect, id));
			id += 1;
		}
	}
}

function draw() {
	background(0);
	ang.add(avel);
	avel.mult(0.9);
	bspeed = lerp(bspeed, tbspeed,0.1);
	ang.y += bspeed;
	rotateX(ang.x);
	rotateY(ang.y);
	rotateZ(ang.z);
	if(partyOn) stretch = lerp(stretch,1, 0.1);
	if (restoring) ang.lerp(start, 0.1);
	zoom = lerp(zoom, ztarget, 0.1);
	scale(zoom);
	if (shift && frameCount % 180 == 0) randomize();
	twist.lerp(createVector(sliderx.value(), slidery.value(), sliderz.value()), 0.1);
	ztarget = sliders.value();
	ptarget = 16 - sliderp.value();
	pscale = lerp(pscale, ptarget, 0.1);
	shader(fx);
	fx.setUniform("uMatcapTexture", capture);
	for (let p of panels) {
		p.move();
		p.show();
	}
	checkInputs();
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
